SELECT "categories"."id", ((SELECT AVG("orm_values"."orm_value") FROM (SELECT DISTINCT "products"."id" AS "orm_pk", "products"."status" AS "orm_value" FROM "categories" AS "orm_rel_1" LEFT JOIN "aggregate_products" AS "products" ON "products"."aggregate_category_id" = "orm_rel_1"."id" WHERE "orm_rel_1"."id" = "categories"."id" AND "products"."id" IS NOT NULL) AS "orm_values")) AS "avg", ((SELECT MIN("orm_values"."orm_value") FROM (SELECT DISTINCT "products"."id" AS "orm_pk", "products"."status" AS "orm_value" FROM "categories" AS "orm_rel_2" LEFT JOIN "aggregate_products" AS "products" ON "products"."aggregate_category_id" = "orm_rel_2"."id" WHERE "orm_rel_2"."id" = "categories"."id" AND "products"."id" IS NOT NULL) AS "orm_values")) AS "min", ((SELECT MAX("orm_values"."orm_value") FROM (SELECT DISTINCT "products"."id" AS "orm_pk", "products"."status" AS "orm_value" FROM "categories" AS "orm_rel_3" LEFT JOIN "aggregate_products" AS "products" ON "products"."aggregate_category_id" = "orm_rel_3"."id" WHERE "orm_rel_3"."id" = "categories"."id" AND "products"."id" IS NOT NULL) AS "orm_values")) AS "max" FROM "categories" GROUP BY "categories"."id";
